var t=[{title:`Types de portages courants`,text:`Un portage du fermier utilise un poids dans chaque main. Un portage d’une seule main utilise un poids d’un seul côté, donc votre tronc doit résister à l’inclinaison latérale. Un portage avant tient la charge près de la poitrine, et un portage au-dessus de la tête demande plus de stabilité de l’épaule et plus de hauteur libre. Chaque position change les muscles et l’habileté en jeu.`},{title:`Technique de base`,text:`Choisissez une charge que vous pouvez tenir fermement pendant toute la marche, tenez-vous droit dans une posture confortable et marchez à pas délibérés. Gardez le poids bien en main, ne vous penchez pas beaucoup vers lui ni à l’opposé, et continuez à respirer pendant une longue marche. Ralentissez dans les virages et gardez votre trajet dégagé.`},{title:`Comment doser les portages`,text:`Les portages se comptent en distance ou en durée plutôt qu’en répétitions. Par exemple, portez deux haltères que vous pouvez tenir fermement pendant 20–30 secondes, reposez-vous, puis recommencez. Quand votre prise et votre posture restent les mêmes, ajoutez un peu de distance, de temps ou de poids. Un poids plus lourd n’aide pas s’il rend vos pas précipités et irréguliers.`},{title:`Espace et sécurité`,text:`Vérifiez que votre parcours offre assez de sol dégagé, une surface antidérapante et ni personnes ni objets sur le chemin. Posez les poids avec contrôle, et ne les lâchez pas. Évitez les portages au-dessus de la tête sous un plafond bas ou quand vous n’êtes pas sûr du contrôle de votre épaule. Faites toujours les portages d’un seul côté des deux côtés.`},{title:`Avec TrainUp`,text:`Les portages peuvent occuper une place de renforcement quand vous avez le matériel et la place pour marcher. Votre programme vérifie la taille du sol indiquée dans Profil. Si votre dos ou vos mains limitent la charge sur la colonne ou le travail de prise que vous pouvez supporter, ajoutez cette zone du corps comme limite dans Profil pour que le programme puisse écarter les exercices qui ne conviennent pas.`}];var r=[{label:`Bibliothèque d’exercices de l’ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA : sécurité et fondamentaux du renforcement`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:t,sources:r};export{n as default,t as sections,r as sources};